pub fn dotp(&self, rhs: &Self) -> T {
    let (self_m, self_n) = self.dim();
    let (rhs_m, rhs_n) = rhs.dim();

    assert_eq!(self_n, rhs_m, "Incompatible dimensions for dot product");

    let mut result = T::zero();
    for i in 0..self_m {
        for j in 0..rhs_n {
            result = result + self[i] * rhs[j];
        }
    }
    result
}

